 value: string;
}

interface ResultCard {
 caseNumber: string;
 etaResponse: string;
 bus: string;
 route: string;
 stop: string;
 issueType: string;
}

type FlowStep =
 | "idle"
 | "select_bus"
 | "select_route"
 | "select_stop"
 | "describe"
 | "location"
 | "submitting"
 | "result";

type IssueFlowType = "bus_delay" | "bus_not_arrived" | null;

interface FlowState {
 step: FlowStep;
 flowType: IssueFlowType;
 busId: string;
 busLabel: string;
 routeId: string;
 routeLabel: string;
 stopId: string;
 stopLabel: string;
 description: string;
 latitude: string;
 longitude: string;
}

