","import React, { useState, useEffect } from "react";

interface CaseRecord {
 sys_id: string;
 u_number: { display_value: string };
 u_case_number: { display_value: string };
 u_issue_type: { display_value: string };
 u_state: { display_value: string };
 u_priority: { display_value: string };
 u_short_description: { display_value: string };
 u_description: { display_value: string };
 u_solution_response: { display_value: string };
 u_resolution_notes: { display_value: string };
 u_current_bus: { display_value: string };
 u_current_route: { display_value: string };
 u_current_bus_stop: { display_value: string };
 sys_created_on: { display_value: string };
}

const API_BASE = "/api/now/table";

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 "Content-Type": "application/json",
 Accept: "application/json",
 };
 if ((window as any).g_ck) {
 headers["X-UserToken"] = (window as any).g_ck;
 }
 return headers;
}

const issueTypes = ["All", "Bus Delay", "Bus Not Arrived", "Overcrowded", "Route Change Request"];
const stateFilters = ["All States", "Open", "In Progress", "Resolved", "Approved"];

function getBadgeClass(issueType: string): string {
 const t = issueType?.toLowerCase() || "";
 if (t.includes("delay")) return "ms-badge-yellow";
 if (t.includes("not arrived")) return "ms-badge-red";
 if (t.includes("overcrowded")) return "ms-badge-red";
 if (t.includes("route")) return "ms-badge-blue";
 return "ms-badge-blue";
}

function getStateBadgeClass(state: string): string {
 const s = state?.toLowerCase() || "";
 if (s.includes("open")) return "ms-badge-yellow";
 if (s.includes("progress")) return "ms-badge-blue";
 if (s.includes("resolved")) return "ms-badge-green";
 if (s.includes("approved")) return "ms-badge-green";
 return "ms-badge-yellow";
}

export default function AdminHome() {
 const [cases, setCases] = useState<CaseRecord[]>([]);
 const [loading, setLoading] = useState(true);
 const [selectedIssueType, setSelectedIssueType] = useState("All");
 const [selectedState, setSelectedState] = useState("All States");
 const [selectedCase, setSelectedCase] = useState<CaseRecord | null>(null);
 const [actionLoading, setActionLoading] = useState(false);

 const fetchCases = async () => {
 try {
 const res = await fetch(
 `${API_BASE}/u_transportation_case?sysparm_display_value=all&sysparm_limit=50&sysparm_query=ORDERBYDESCsys_created_on`,
 { headers: getHeaders() }
 );
 const data = await res.json();
 setCases(data.result || []);
 } catch (e) {
 console.error("Failed to fetch cases:", e);
 } finally {
 setLoading(false);
 }
 };

 useEffect(() => {
 fetchCases();
 }, []);

 const filteredCases = cases.filter((c) => {
 const typeMatch =
 selectedIssueType === "All" ||
 (c.u_issue_type?.display_value || "").toLowerCase().includes(selectedIssueType.toLowerCase());
 const stateMatch =
 selectedState === "All States" ||
 (c.u_state?.display_value || "").toLowerCase().includes(selectedState.toLowerCase());
 return typeMatch && stateMatch;
 });

 const handleAction = async (caseRecord: CaseRecord, newState: string) => {
 setActionLoading(true);
 try {
 await fetch(`${API_BASE}/u_transportation_case/${caseRecord.sys_id}`, {
 method: "PATCH",
 headers: getHeaders(),
 body: JSON.stringify({ u_state: newState }),
 });
 // Refresh
 await fetchCases();
 setSelectedCase(null);
 } catch (e) {
 console.error("Failed to update case:", e);
 } finally {
 setActionLoading(false);
 }
 };

 if (loading) {
 return (
 <div className="ms-screen">
 <p>Loading admin console...</p>
 </div>
 );
 }

 return (
 <div className="ms-screen">
 {/* Header */}
 <div className="ms-page-header">
 <span style={{ fontSize: "1.5rem" }}>📊</span>
 <h1 className="ms-page-title">Admin Console</h1>
 <span className="ms-stat-badge">{cases.length}</span>
 </div>

 {/* Filter: Issue Type */}
 <div className="ms-admin-filter-row">
 {issueTypes.map((t) => (
 <button
 key={t}
 className={`ms-filter-chip ${selectedIssueType === t ? "ms-filter-active" : ""}`}
 onClick={() => setSelectedIssueType(t)}
 >
 {t}
 </button>
 ))}
 </div>

 {/* Filter: State */}
 <div className="ms-admin-filter-row" style={{ marginTop: "8px" }}>
 {stateFilters.map((s) => (
 <button
 key={s}
 className={`ms-filter-chip ${selectedState === s ? "ms-filter-active" : ""}`}
 onClick={() => setSelectedState(s)}
 >
 {s}
 </button>
 ))}
 </div>

 {/* Case List */}
 <div className="ms-request-list" style={{ marginTop: "1rem" }}>
 {filteredCases.length === 0 ? (
 <p className="ms-page-subtitle">No cases match the selected filters.</p>
 ) : (
 filteredCases.map((c) => (
 <div
 key={c.sys_id}
 className="ms-admin-case-card"
 onClick={() => setSelectedCase(c)}
 >
 <div className="ms-request-top">
 <span className="ms-request-id">
 {c.u_number?.display_value || c.u_case_number?.display_value || "—"}
 </span>
 <span className={`ms-badge ${getStateBadgeClass(c.u_state?.display_value)}`}>
 {c.u_state?.display_value || "Open"}
 </span>
 </div>
 <div className="ms-request-title">
 {c.u_short_description?.display_value || "No description"}
 </div>
 <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "4px" }}>
 <span className={`ms-badge ${getBadgeClass(c.u_issue_type?.display_value)}`}>
 {c.u_issue_type?.display_value || "—"}
 </span>
 </div>
 <div className="ms-request-meta" style={{ marginTop: "8px" }}>
 <span>{c.u_current_bus?.display_value ? `Bus: ${c.u_current_bus.display_value}` : ""}</span>
 <span>{c.sys_created_on?.display_value || ""}</span>
 </div>
 </div>
 ))
 )}
 </div>

 {/* Case Detail Modal */}
 {selectedCase && (
 <div className="ms-case-modal" onClick={() => setSelectedCase(null)}>
 <div className="ms-case-modal-content" onClick={(e) => e.stopPropagation()}>
 <div className="ms-detail-header">
 <div>
 <div className="ms-request-id" style={{ marginBottom: "4px" }}>
 {selectedCase.u_number?.display_value || selectedCase.u_case_number?.display_value}
 </div>
 <div className="ms-detail-title">
 {selectedCase.u_short_description?.display_value || "Case Detail"}
 </div>
 </div>
 <button
 className="ms-back-btn"
 onClick={() => setSelectedCase(null)}
 >
 ✕
 </button>
 </div>

 <div className="ms-detail-fields">
 <div className="ms-detail-field">
 <span className="ms-detail-label">Issue Type</span>
 <span className={`ms-badge ${getBadgeClass(selectedCase.u_issue_type?.display_value)}`}>
 {selectedCase.u_issue_type?.display_value || "—"}
 </span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">State</span>
 <span className={`ms-badge ${getStateBadgeClass(selectedCase.u_state?.display_value)}`}>
 {selectedCase.u_state?.display_value || "—"}
 </span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">Priority</span>
 <span className="ms-detail-value">{selectedCase.u_priority?.display_value || "—"}</span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">Bus</span>
 <span className="ms-detail-value">{selectedCase.u_current_bus?.display_value || "—"}</span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">Route</span>
 <span className="ms-detail-value">{selectedCase.u_current_route?.display_value || "—"}</span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">Bus Stop</span>
 <span className="ms-detail-value">{selectedCase.u_current_bus_stop?.display_value || "—"}</span>
 </div>
 <div className="ms-detail-field">
 <span className="ms-detail-label">Reported</span>
 <span className="ms-detail-value">{selectedCase.sys_created_on?.display_value || "—"}</span>
 </div>
 </div>

 {selectedCase.u_description?.display_value && (
 <div className="ms-detail-description" style={{ marginBottom: "12px" }}>
 <span className="ms-detail-label">Description</span>
 <p>{selectedCase.u_description.display_value}</p>
 </div>
 )}

 {selectedCase.u_solution_response?.display_value && (
 <div className="ms-detail-description" style={{ marginBottom: "12px" }}>
 <span className="ms-detail-label">Solution Response</span>
 <p>{selectedCase.u_solution_response.display_value}</p>
 </div>
 )}

 {selectedCase.u_resolution_notes?.display_value && (
 <div className="ms-detail-description" style={{ marginBottom: "12px" }}>
 <span className="ms-detail-label">Resolution Notes</span>
 <p>{selectedCase.u_resolution_notes.display_value}</p>
 </div>
 )}

 <div className="ms-admin-actions">
 <button
 className="ms-admin-action-btn ms-admin-action-approve"
 disabled={actionLoading}
 onClick={() => handleAction(selectedCase, "approved")}
 >
 ✓ Approve
 </button>
 <button
 className="ms-admin-action-btn ms-admin-action-resolve"
 disabled={actionLoading}
 onClick={() => handleAction(selectedCase, "resolved")}
 >
 ✓ Resolve
 </button>
 </div>
 </div>
 </div>
 )}
 </div>
 );
}
