","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";
import HomeScreen from "./components/HomeScreen";
import ReportIssueScreen from "./components/ReportIssueScreen";
import IssueFormScreen from "./components/IssueFormScreen";
import MyBusScreen from "./components/MyBusScreen";
import BusPassScreen from "./components/BusPassScreen";
import MyRequestsScreen from "./components/MyRequestsScreen";
import RequestDetailScreen from "./components/RequestDetailScreen";
import LostFoundScreen from "./components/LostFoundScreen";
import EmergencyScreen from "./components/EmergencyScreen";
import ProfileScreen from "./components/ProfileScreen";
import BottomNav from "./components/BottomNav";
import ChatWidget from "./components/ChatWidget";
import RoleSwitcher from "./components/RoleSwitcher";
import DriverHome from "./components/DriverHome";
import DriverNav from "./components/DriverNav";
import AdminHome from "./components/AdminHome";
import AdminNav from "./components/AdminNav";

type Role = "student" | "driver" | "admin";

interface ViewState {
 view: string;
 type: string | null;
 id: string | null;
}

function getRoleFromUrl(): Role {
 const params = new URLSearchParams(window.location.search);
 const role = params.get("role");
 if (role === "driver" || role === "admin") return role;
 return "student";
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 type: params.get("type") || null,
 id: params.get("id") || null,
 };
}

export default function App() {
 const [role, setRole] = useState<Role>(getRoleFromUrl);
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => {
 setCurrentView(getViewFromUrl());
 setRole(getRoleFromUrl());
 };
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigate = useCallback(
 (viewName: string, extras?: { type?: string; id?: string }) => {
 const params = new URLSearchParams(window.location.search);
 params.set("view", viewName);
 if (extras?.type) {
 params.set("type", extras.type);
 } else {
 params.delete("type");
 }
 if (extras?.id) {
 params.set("id", extras.id);
 } else {
 params.delete("id");
 }
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState({}, "", path);
 setCurrentView({
 view: viewName,
 type: extras?.type || null,
 id: extras?.id || null,
 });
 },
 []
 );

 const { view, type, id } = currentView;

 // Student screens
 const renderStudentScreen = () => {
 switch (view) {
 case "home":
 return <HomeScreen navigate={navigate} />;
 case "report":
 return <ReportIssueScreen navigate={navigate} />;
 case "issue-form":
 return <IssueFormScreen navigate={navigate} issueType={type} />;
 case "mybus":
 return <MyBusScreen navigate={navigate} />;
 case "buspass":
 return <BusPassScreen navigate={navigate} />;
 case "requests":
 return <MyRequestsScreen navigate={navigate} />;
 case "request-detail":
 return <RequestDetailScreen navigate={navigate} requestId={id} />;
 case "lostfound":
 return <LostFoundScreen navigate={navigate} />;
 case "emergency":
 return <EmergencyScreen navigate={navigate} />;
 case "profile":
 return <ProfileScreen navigate={navigate} />;
 default:
 return <HomeScreen navigate={navigate} />;
 }
 };

 // Driver screens
 const renderDriverScreen = () => {
 return <DriverHome />;
 };

 // Admin screens
 const renderAdminScreen = () => {
 return <AdminHome />;
 };

 return (
 <div className="ms-app">
 <RoleSwitcher role={role} setRole={setRole} />
 <div className="ms-content">
 {role === "student" && renderStudentScreen()}
 {role === "driver" && renderDriverScreen()}
 {role === "admin" && renderAdminScreen()}
 </div>
 {role === "student" && <BottomNav currentView={view} navigate={navigate} />}
 {role === "driver" && <DriverNav currentView={view} navigate={navigate} />}
 {role === "admin" && <AdminNav currentView={view} navigate={navigate} />}
 {role === "student" && <ChatWidget />}
 </div>
 );
}
